<script setup>
import {ref,reactive,computed,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';
const API='/agarwood/api/v1';const token=ref(sessionStorage.getItem('auth')||'');const username=ref('admin'),password=ref(''),menu=ref('products'),rows=ref([]),categories=ref([]),sites=reactive({}),dialog=ref(false),mode=ref('create'),editId=ref(null),busy=ref(false);const form=reactive({});const inquiryRows=ref([]);const fileInput=ref(null);
const title=computed(()=>({products:'产品管理',categories:'分类管理',articles:'沉香知识',settings:'网站设置',inquiries:'客户咨询'})[menu.value]);
const productDefaults=()=>({name:'',slug:'',sku:'',category_id:null,summary:'',description:'',image:'',images:[],origin:'',scent:'',usage:'',price_mode:'inquiry',price:null,unit:'件',stock_status:'available',status:'draft',featured:false,sort_order:0});
const articleDefaults=()=>({title:'',slug:'',excerpt:'',body:'',cover:'',status:'draft',sort_order:0});const categoryDefaults=()=>({name:'',slug:'',sort_order:0,visible:true});
async function api(path,options={}){const r=await fetch(API+path,{...options,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...(options.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401){token.value='';sessionStorage.removeItem('auth')}throw new Error(typeof d.detail==='string'?d.detail:'请求失败')}return d}
async function login(){try{const x=await api('/admin/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});token.value=x.access_token;sessionStorage.setItem('auth',token.value);password.value='';await load();ElMessage.success('登录成功')}catch(e){ElMessage.error(e.message)}}
function logout(){token.value='';sessionStorage.removeItem('auth')}
async function load(){if(!token.value)return;try{categories.value=await api('/admin/categories');if(menu.value==='products')rows.value=await api('/admin/products');if(menu.value==='categories')rows.value=categories.value;if(menu.value==='articles')rows.value=await api('/admin/articles');if(menu.value==='settings')Object.assign(sites,await api('/admin/settings'));if(menu.value==='inquiries')inquiryRows.value=await api('/admin/inquiries')}catch(e){ElMessage.error(e.message)}}
function changeMenu(m){menu.value=m;load()}
function showCreate(){mode.value='create';editId.value=null;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,menu.value==='products'?productDefaults():menu.value==='articles'?articleDefaults():categoryDefaults());dialog.value=true}
function showEdit(row){mode.value='edit';editId.value=row.id;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,JSON.parse(JSON.stringify(row)));dialog.value=true}
async function save(){busy.value=true;try{const path='/admin/'+menu.value+(editId.value?'/'+editId.value:'');const {id,created_at,updated_at,...payload}=form;if(menu.value==='products'){payload.category_id=payload.category_id||null;payload.price=payload.price_mode==='fixed'?payload.price:null;payload.images=payload.image?[payload.image]:[]}await api(path,{method:editId.value?'PUT':'POST',body:JSON.stringify(payload)});ElMessage.success('保存成功');dialog.value=false;await load()}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function remove(row){try{await ElMessageBox.confirm('确定删除？已发布产品建议下架而非删除。','确认操作');await api('/admin/'+menu.value+'/'+row.id,{method:'DELETE'});ElMessage.success('已删除');load()}catch(e){if(e!=='cancel')ElMessage.error(e.message)}}
async function saveSite(){try{await api('/admin/settings',{method:'PUT',body:JSON.stringify(sites)});ElMessage.success('网站设置已保存')}catch(e){ElMessage.error(e.message)}}
async function setInquiry(row,status){try{await api('/admin/inquiries/'+row.id,{method:'PUT',body:JSON.stringify({status})});load()}catch(e){ElMessage.error(e.message)}}
async function uploadImage(file){try{const data=new FormData();data.append('file',file.raw);const r=await fetch(API+'/admin/upload',{method:'POST',headers:{Authorization:'Bearer '+token.value},body:data});const d=await r.json();if(!r.ok)throw new Error(d.detail||'上传失败');if(menu.value==='products')form.image=d.url;else if(menu.value==='articles')form.cover=d.url;ElMessage.success('上传成功')}catch(e){ElMessage.error(e.message)}}
onMounted(()=>{if(token.value)load()});
</script>
<template><div v-if="!token" class="login"><el-card style="width:390px;max-width:92vw"><h2>沉香官网 · 管理后台</h2><el-form @submit.prevent="login" label-position="top"><el-form-item label="账号"><el-input v-model="username" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password autocomplete="current-password" @keyup.enter="login"/></el-form-item><el-button type="primary" style="width:100%" @click="login">登录</el-button></el-form></el-card></div><el-container v-else class="layout"><el-aside width="210px" class="sidebar"><h2>◈ 沉香雅集</h2><el-menu :default-active="menu" @select="changeMenu"><el-menu-item index="products">产品管理</el-menu-item><el-menu-item index="categories">分类管理</el-menu-item><el-menu-item index="articles">文章管理</el-menu-item><el-menu-item index="settings">品牌资料</el-menu-item><el-menu-item index="inquiries">咨询线索</el-menu-item></el-menu><el-button text @click="logout">退出登录</el-button></el-aside><el-main><div class="toolbar"><h1>{{title}}</h1><el-button v-if="['products','categories','articles'].includes(menu)" type="primary" @click="showCreate">+ 新增</el-button><el-button v-if="menu==='settings'" type="primary" @click="saveSite">保存设置</el-button></div>
<el-table v-if="menu==='products'" :data="rows" border><el-table-column label="封面" width="85"><template #default="{row}"><img :src="row.image||'/agarwood/assets/product-chips.svg'" class="thumb"/></template></el-table-column><el-table-column prop="name" label="产品" min-width="180"/><el-table-column prop="sku" label="编码" width="120"/><el-table-column label="价格" width="130"><template #default="{row}">{{row.price_mode==='fixed'&&row.price!=null?'¥'+row.price:'询价'}}</template></el-table-column><el-table-column prop="status" label="发布状态" width="100"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="showEdit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<el-table v-if="menu==='categories'" :data="rows" border><el-table-column prop="name" label="分类"/><el-table-column prop="slug" label="Slug"/><el-table-column prop="visible" label="显示"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button link @click="showEdit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<el-table v-if="menu==='articles'" :data="rows" border><el-table-column prop="title" label="文章"/><el-table-column prop="slug" label="Slug"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button link @click="showEdit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<el-form v-if="menu==='settings'" label-width="125px" class="settings"><el-form-item v-for="(label,key) in {brand_name:'品牌名称',slogan:'品牌标语',hero_title:'首页主标题',hero_subtitle:'首页副标题',hero_image:'首页图片路径',about:'公司介绍',phone:'电话',wechat:'微信',whatsapp:'WhatsApp',email:'邮箱',address:'地址'}" :key="key" :label="label"><el-input v-if="['about','hero_subtitle'].includes(key)" v-model="sites[key]" type="textarea" :rows="4"/><el-input v-else v-model="sites[key]"/></el-form-item><el-button type="primary" @click="saveSite">保存全部</el-button></el-form>
<el-table v-if="menu==='inquiries'" :data="inquiryRows" border><el-table-column prop="created_at" label="时间" width="170"/><el-table-column prop="name" label="称呼" width="110"/><el-table-column prop="contact" label="联系方式" min-width="150"/><el-table-column prop="message" label="留言" min-width="180"/><el-table-column label="跟进状态" width="155"><template #default="{row}"><el-select :model-value="row.status" @change="v=>setInquiry(row,v)"><el-option label="新咨询" value="new"/><el-option label="已联系" value="contacted"/><el-option label="已结束" value="closed"/></el-select></template></el-table-column></el-table>
<el-dialog v-model="dialog" :title="(mode==='edit'?'编辑':'新增')+title" width="min(760px,95vw)" destroy-on-close><el-form label-position="top" class="editor"><template v-if="menu==='products'"><el-row :gutter="16"><el-col :span="12"><el-form-item label="产品名称"><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="商品编码 SKU"><el-input v-model="form.sku"/></el-form-item></el-col></el-row><el-form-item label="英文网址 slug（小写字母/数字/横线）"><el-input v-model="form.slug"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="分类"><el-select v-model="form.category_id" style="width:100%"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="发布状态"><el-select v-model="form.status" style="width:100%"><el-option label="草稿" value="draft"/><el-option label="上架" value="published"/><el-option label="下架" value="hidden"/></el-select></el-form-item></el-col></el-row><el-form-item label="产品摘要"><el-input v-model="form.summary" type="textarea"/></el-form-item><el-form-item label="详情介绍（纯文本）"><el-input v-model="form.description" type="textarea" :rows="5"/></el-form-item><el-form-item label="封面图"><el-input v-model="form.image" placeholder="/uploads/xxx.webp 或 /agarwood/assets/xxx.svg"/><el-upload :show-file-list="false" :auto-upload="false" :on-change="uploadImage" accept="image/png,image/jpeg,image/webp"><el-button size="small" style="margin-top:8px">上传图片</el-button></el-upload></el-form-item><el-row :gutter="14"><el-col :span="12"><el-form-item label="价格模式"><el-select v-model="form.price_mode"><el-option label="询价" value="inquiry"/><el-option label="显示价格" value="fixed"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="价格"><el-input-number v-model="form.price" :disabled="form.price_mode!=='fixed'" :min="0" :precision="2"/></el-form-item></el-col></el-row><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="来源说明"><el-input v-model="form.origin"/></el-form-item><el-form-item label="香气描述"><el-input v-model="form.scent"/></el-form-item><el-form-item label="适用场景"><el-input v-model="form.usage"/></el-form-item><el-form-item label="库存状态"><el-select v-model="form.stock_status"><el-option label="有货" value="available"/><el-option label="售罄" value="sold_out"/></el-select></el-form-item><el-form-item><el-checkbox v-model="form.featured">首页推荐</el-checkbox></el-form-item></template>
<template v-if="menu==='categories'"><el-form-item label="分类名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="Slug"><el-input v-model="form.slug"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort_order"/></el-form-item><el-checkbox v-model="form.visible">前台显示</el-checkbox></template>
<template v-if="menu==='articles'"><el-form-item label="文章标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="Slug"><el-input v-model="form.slug"/></el-form-item><el-form-item label="摘要"><el-input v-model="form.excerpt" type="textarea"/></el-form-item><el-form-item label="正文（纯文本，支持换行）"><el-input v-model="form.body" type="textarea" :rows="9"/></el-form-item><el-form-item label="封面图片"><el-input v-model="form.cover"/><el-upload :show-file-list="false" :auto-upload="false" :on-change="uploadImage" accept="image/png,image/jpeg,image/webp"><el-button size="small" style="margin-top:8px">上传图片</el-button></el-upload></el-form-item><el-form-item label="发布状态"><el-select v-model="form.status"><el-option label="草稿" value="draft"/><el-option label="发布" value="published"/><el-option label="隐藏" value="hidden"/></el-select></el-form-item></template>
</el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog>
</el-main></el-container></template>
